-- Generated by Murakumo for duckdb: the project as plain SQL, without dbt.
CREATE OR REPLACE VIEW staging.stg_tpch_erp__region AS
with source as (

    select * from raw_tpch_erp.region

),

final as (

    select
        cast(source.r_regionkey as INTEGER) as r_regionkey,
        cast(source.r_name as VARCHAR) as r_name,
        cast(source.r_comment as VARCHAR) as r_comment,
        source._ingested_at as _ingested_at,
        source._batch_id as _batch_id,
        'tpch_erp' as _source_system,
        MD5(COALESCE(CAST(source.r_regionkey AS TEXT), '') || '|' || COALESCE(CAST(source.r_name AS TEXT), '') || '|' || COALESCE(CAST(source.r_comment AS TEXT), '')) as _record_hash
    from source

)

select * from final;
